//--------------------------------------------------------------------------------------//

Boolean dei_rf1_nvfs_init( void )
{    
    static  Dei_Rf1_Hhu     cur_dei_hhu;
            Boolean         status         = FALSE ;


    if(nvfs_rd(nvfs_rem_dei , &dei_rf1_hhu) != NVFS_OK)
    {      
        status |= nvfs_wr_create( nvfs_rem_dei  , &cur_dei_hhu , sizeof (Dei_Rf1_Hhu) ) == NVFS_OK ;              
    }

    if(status)
    {
      status |= nvram_usr_commit() ;
    }

    status |= nvfs_rd(nvfs_rem_dei , &dei_rf1_hhu) == NVFS_OK ;

    return status ;   
}
            

//--------------------------------------------------------------------------------------//

void dei_rf1_nvfs_update( void )
{
    Exec_Q_Msg *exec_q_msg = NULL; 
     
    exec_q_msg = exec_q_remove( dei_rf1_vars.exec_q_free );
		
	if( exec_q_msg )
	{
		exec_q_insert( exec_q_msg , (Exec_Func)dei_rf1_nvfs_update_execute );
	}
}

//--------------------------------------------------------------------------------------//    

void dei_rf1_nvfs_delete(void)
{
	nvfs_delete( nvfs_rem_dei );

	TRACE_DEI_RF1("[DEI_RF1_NVFS_DELETE]\n\r");
}

//--------------------------------------------------------------------------------------//    

static void dei_rf1_nvfs_update_execute(void)
{
	if(nvfs_wr( nvfs_rem_dei , &dei_rf1_hhu ) == NVFS_OK)
	{
		TRACE_DEI_RF1("DEI_RF1_NVFS_UPDATE_OK]\n\r");
	}
	else
	{
		TRACE_DEI_RF1("DEI_RF1_NVFS_UPDATE_ERROR]\n\r");
	}
}
	
